// This is not autogenerated.
package event

import (
	"errors"
	"fmt"

	errorcodev1beta3 "github.com/meshery/schemas/models/v1beta3/errorcode"
)

// This file is hand-written. It holds the rules of an error event's
// metadata.error (EventError) that JSON Schema cannot state
// (docs/error-definition-contract.md), mirrored by
// typescript/errors/errorDefinition.ts.

// Paired reports whether the error carries nested causes, so each
// remediation is tied to the cause it answers. An error with only flat lists
// is unpaired, and nothing may pair its lists by position.
func (e EventError) Paired() bool {
	return e.ProbableCauses != nil
}

// FlatLists returns the error's flat lists: derived from its nested causes
// when it has them, otherwise the unpaired lists it carries.
func (e EventError) FlatLists() (probableCause, suggestedRemediation []string) {
	if e.ProbableCauses != nil {
		return errorcodev1beta3.FlattenProbableCauses(*e.ProbableCauses)
	}
	clone := func(list *[]string) []string {
		if list == nil {
			return []string{}
		}
		return append([]string{}, (*list)...)
	}
	return clone(e.ProbableCause), clone(e.SuggestedRemediation)
}

// Validate checks the rules of metadata.error that JSON Schema cannot state:
// the nested causes follow errorcode.ValidateProbableCauses, flat lists
// carried beside them equal the derivation, and, when the error carries
// nested causes, every matched cause is one of them. The returned error
// joins one *errorcode.ContractError per broken rule, or is nil.
func (e EventError) Validate() error {
	if e.ProbableCauses == nil {
		return nil // unpaired: flat lists only, nothing to cross-check
	}
	errs := []error{
		errorcodev1beta3.ValidateProbableCauses(*e.ProbableCauses, "probableCauses"),
		errorcodev1beta3.ValidateFlatLists(e.ProbableCauses, e.ProbableCause, e.SuggestedRemediation, ""),
	}
	ids := map[string]bool{}
	for _, cause := range *e.ProbableCauses {
		ids[cause.ID] = true
	}
	if e.MatchedCauses != nil {
		for i, match := range *e.MatchedCauses {
			if !ids[match.CauseID] {
				errs = append(errs, &errorcodev1beta3.ContractError{
					Path:    fmt.Sprintf("matchedCauses[%d].causeId", i),
					Message: fmt.Sprintf("matched cause %q is not one of probableCauses", match.CauseID),
				})
			}
		}
	}
	return errors.Join(errs...)
}
